// 27xSOLved · Química Analítica Cualitativa 5.º · GUÍAS DE EJERCITACIÓN N° 1 a 4 (consignas).
// Reemplaza las versiones anteriores de las guías por las consignas de la edición vigente.
// Por ahora sólo consignas: las resoluciones se agregan después en el campo `solution` de cada ítem.
// Ubicación: Guía 1 entera en Ácido-base I · Guía 2 en Ácido-base II (reguladoras en Buffer; 8 y 17 en Complejos)
// · Guía 3 monopróticos en Ácido-base I, polipróticos y sales en Ácido-base II, reguladoras en Buffer
// · Guía 4 en Precipitación (1–10, 17), Complejos (11–16, 18, 19 e integraciones) y Redox (20–26).
(function(){
  'use strict';
  const data=window.ET27_QAC5,A=window.ET27QAC;if(!data||!A)return;
  const {st,addEx}=A;
  const U=id=>data.units.find(u=>u.id===id);

  // ---------------------------------------------------------------------
  // 1) Quitar las versiones anteriores de las guías (y las integraciones de la Guía 4)
  // ---------------------------------------------------------------------
  const OLD=['g2','g3m','g3p','g3s','bg2','bg3','cg','pg4','rg4'];
  data.units.forEach(u=>{
    u.exercises=(u.exercises||[]).filter(e=>!OLD.includes(e.group)&&!/^int\d/.test(e.id));
    u.sections=u.sections.filter(s=>!OLD.some(g=>s.key===`qac-ej-${g}`));
    u.sections.forEach(s=>{if(s.exercises&&/^Integraci[oó]n(es)? y evaluaciones/.test(s.label))s.label=s.label.replace(/^Integraci[oó]n(es)? y evaluaciones/,'Evaluaciones')});
  });

  // ---------------------------------------------------------------------
  // 2) Consignas
  // ---------------------------------------------------------------------
  const GUIDES=[];
  const guide=(uid,group,label,intro,prefix,idp)=>{const list=[];GUIDES.push(group);
    const add=(n,title,statement,tag)=>list.push({id:`${idp}-${n}`,tag:tag||`${prefix} · EJ. ${n}`,title,statement,solution:'',answer:''});
    return {add,done:()=>addEx(uid,{group,label,intro,kicker:'GUÍA DE EJERCITACIÓN'},list)};};
  const ol=items=>`<ol type="a">${items.map(x=>`<li>${x}</li>`).join('')}</ol>`;
  const note=t=>`<p class="qacGuideNote">${t}</p>`;

  // ===================== GUÍA N° 1 · Conceptos introductorios =====================
  let g=guide('acido-base','g1','Guía 1 · Conceptos introductorios','<p>Guía N° 1 completa, en el orden de la guía: ejercicios 1 a 15, ejercicios de integración y ejercicio de integración teórica (lectura del Burriel).</p>','GUÍA 1','g1');
  g.add(1,'BaSO₄ en contacto con su sobrenadante y H₂SO₄',st('Se tiene sulfato de bario en contacto con su sobrenadante. Se agrega solución de ácido sulfúrico (1.ª disociación: fuerte; 2.ª disociación: débil). Justifique en base a los conceptos teóricos adecuados por qué:',['el sulfato de bario no se disuelve en agua;','aumenta la cantidad de sal luego de agregar el ácido.']));
  g.add(2,'Disociación de HCl y HAc en mezcla',st('Analizar cualitativamente la disociación de la sustancia en negrita de las siguientes mezclas, explicando claramente cómo se ve afectada su disociación por la otra sustancia:',['<b>HCl</b> (electrolito fuerte) y HAc (electrolito débil)','HCl (electrolito fuerte) y <b>HAc</b> (electrolito débil)']));
  g.add(3,'Sulfato cúprico y amoníaco',st('Se prepara una solución de sulfato cúprico (color azul). Se incorpora solución de amoníaco (electrolito débil) hasta aparición de un precipitado. Luego, se continúa agregando solución de amoníaco hasta disolución total del precipitado. La disolución final es de un color azul intenso.',['Esquematice la sucesión de eventos ocurridos en la situación experimental presentada, justificando si el sistema se encuentra en equilibrio o fuera de él.','Justifique a nivel teórico por qué el sulfato cúprico se disuelve en agua.','Justifique empleando los argumentos teóricos apropiados por qué ocurren los cambios identificados en a.','A la disolución final se le incorpora gota a gota solución de ácido clorhídrico (electrolito fuerte). Al cabo de cierta cantidad de gotas, la solución vuelve al color azul original del sulfato cúprico. Explique por qué.']));
  g.add(4,'Nitrato de plata y HCl concentrado',st('Se tiene una solución de nitrato de plata 0,1 M. Se le agrega gota a gota solución de ácido clorhídrico concentrado (electrolito fuerte). Aparece un precipitado color blanco, y luego se disuelve en solución acuosa.',['Justifique empleando argumentos teóricos por qué se disolvió el precipitado.','Para el sistema final, escriba todas las expresiones de la ley de acción de masas.']));
  g.add(5,'Carácter ácido del catión férrico',st('El catión férrico es considerado un catión ácido porque en solución acuosa es capaz de reaccionar con agua y precipitar como hidróxido. Justifique el carácter ácido del catión empleando la teoría ácido-base que prefiera.'));
  g.add(6,'Carácter ácido-base según Lewis',st('Justifique, según la teoría de Lewis, cuál es el carácter ácido-base de las siguientes sustancias: pirrolidina, ácido fosfórico y etanol.')+note('Recomendación de la guía: haga las estructuras de Lewis.'));
  g.add(7,'Ley de acción de masas: NH₃ y NaOH',st('El amoníaco se comporta en solución acuosa como una base débil. El hidróxido de sodio en solución acuosa se comporta como una base fuerte. Explique si es aplicable la ley de acción de masas para cada uno de esos compuestos.'));
  g.add(8,'Equilibrios de transferencia de protón',st('Escriba los equilibrios de transferencia de protón de las siguientes especies en solución acuosa, indicando cuáles son los ácidos y bases conjugadas: ion anilinio (C₆H₅NH₃⁺), anión ortofosfato diácido, ácido fórmico (HCOOH), ion hidracinio (NH₂NH₃⁺), anión cianuro, urea (CO(NH₂)₂).'));
  g.add(9,'Carácter anfiprótico',st('Escriba los equilibrios correspondientes al carácter anfiprótico de las especies: carbonato ácido y ortoarseniato ácido.'));
  g.add(10,'Catión sodio neutro y catión aluminio ácido',st('El catión sodio es un catión neutro en tanto que el catión aluminio es un catión ácido. Explicar esto en función del carácter como electrolito de los hidróxidos correspondientes (fuerte / débil).'));
  g.add(11,'Sulfato de zinc y amoníaco',st('A una solución de sulfato de zinc se le agrega gota a gota solución de amoníaco (electrolito débil). Aparece un precipitado que por exceso de solución básica se disuelve. Explicar qué sucede en cada cambio y escribir las expresiones de la ley de acción de masas del sistema en equilibrio.'));
  g.add(12,'Cloruro de cromo (III), amoníaco y agua oxigenada',st('Una solución de cloruro de cromo (III) se trata con una base débil como el amoníaco, apareciendo un precipitado. Ese precipitado en presencia de solución de agua oxigenada forma una solución color amarillo. Explicar qué sucede en cada cambio y escribir las expresiones de la ley de acción de masas del sistema en equilibrio.'));
  g.add(13,'Níquel (II) en solución salina con amoníaco',st('A un tubo conteniendo solución salina (solución de cloruro de sodio 0,9 % m/v) se agrega solución de cloruro de níquel (II), quedando de color verde. Se agrega amoníaco (electrolito débil) hasta coloración azul violácea. Empleando los conceptos teóricos apropiados, justifique lo que ocurre.'));
  g.add(14,'Ácido fosfórico saturado con distintos agregados',st('A una solución saturada de ácido fosfórico (electrolito débil) se le agrega:',['hidróxido de sodio (electrolito fuerte);','ácido nítrico (electrolito fuerte);','hidróxido de calcio (electrolito fuerte).'])+'<p>Explicar en cada caso qué ocurre con la disociación.</p>');
  g.add(15,'Acetona y Brønsted-Lowry',st('La acetona es un solvente. Busque su fórmula en internet y justifique por qué no puede ser empleada la teoría de Brønsted-Lowry para establecer que se trata de una sustancia anfiprótica.'));
  g.add('i1','Cloruro férrico en tres porciones',note('Ejercicio de integración (para resolver en 40 minutos).')+st('Una solución de cloruro férrico se divide en 3 porciones:',['<b>Porción 1:</b> se agrega una base débil como el amoníaco, apareciendo un precipitado. Explicar empleando los conceptos teóricos adecuados el cambio ocurrido y escribir las expresiones de la ley de acción de masas del sistema en equilibrio.','<b>Porción 2:</b> se agrega una base fuerte como el hidróxido de calcio hasta que finaliza la precipitación. Se agrega ácido nítrico (electrolito fuerte) y se disuelve el precipitado. Escribir el sistema final en equilibrio y explicar cuándo la porción 2 estuvo fuera del equilibrio.','<b>Porción 3:</b> se agrega cloruro de sodio. Explicar por qué no se observan cambios en el sistema y justificar si se encuentra en equilibrio.']),'GUÍA 1 · INTEGRACIÓN · 1');
  g.add('i2','Ácido fosfórico con hidróxido de bario',note('Ejercicio de integración (para resolver en 40 minutos).')+st('20 mL de una solución de ácido fosfórico (electrolito débil) se mezclan con 20 mL de una solución de hidróxido de bario (electrolito fuerte). Explicar qué ocurre con la disociación del ácido.'),'GUÍA 1 · INTEGRACIÓN · 2');
  g.done();

  const frag=(t,d)=>`<p class="qacGuideNote"><b>Fragmento del libro:</b> ${t}. ${d}</p><p class="qacGuideNote">El texto completo del fragmento está en la guía impresa (extracto de <i>Química Analítica Cualitativa</i>, Burriel Martí, Lucena Conde, Arribas Jimeno y Hernández Méndez).</p>`;
  g=guide('acido-base','g1t','Guía 1 · Integración teórica (lectura del Burriel)','<p>Ejercicio de integración teórica de los temas de la Guía 1: leer cada fragmento del libro y responder las preguntas de comprensión.</p>','GUÍA 1','g1t');
  g.add('f1','Aumento y disminución de la concentración · ion común',frag('“Aumento de la concentración”, “Interacción de electrolitos. Efecto de ion común” y “Disminución de la concentración”','Trata cómo evoluciona el equilibrio AB(ac) ⇌ A⁺(ac) + B⁻(ac) al agregar AB o uno de sus iones (por ejemplo, desde un electrolito fuerte AC), y al retirar A por formación de un complejo ALₙ con un ligando L')+st('Preguntas de comprensión:',['En el texto, ¿qué errores teóricos encuentra? Aplique los conceptos teóricos vistos en clase.','En términos cinéticos, ¿qué significa “evolución del sistema”?','¿Qué teoría ácido-base emplea el libro en los ejemplos dados? ¿Describe la realidad?','En el ejemplo de la formación del complejo ALₙ, ¿qué representa n?']).replace('<ol type="a">','<ol start="1">'),'GUÍA 1 · INTEGRACIÓN TEÓRICA · 1 a 4');
  g.add('f2','Sistemas polipróticos: ácido débil H₃A y base débil A⁻',frag('“Sistemas polipróticos”','Presenta la disociación progresiva de un ácido H₃A hacia especies menos protonadas y, para el sistema monoprótico HA / A⁻, la protonación de la base A⁻ (ejemplos: ion borato y NH₃) puesta en solución como sal de un catión neutro (NaA)')+st('Preguntas de comprensión:',['¿Qué puede decir respecto de la magnitud de las disociaciones sucesivas? ¿Las disociaciones tienen la misma magnitud?','El sistema descripto antes, ¿a qué tipo de sales corresponde?','¿Puede encontrar algún término no empleado en clase?']).replace('<ol type="a">','<ol start="5">'),'GUÍA 1 · INTEGRACIÓN TEÓRICA · 5 a 7');
  g.add('f3','Base débil A³⁻ (sal Na₃A)',frag('“Base débil A³⁻”','Describe la disociación fuerte de una sal Na₃A y la hidrólisis consecutiva de la base débil A³⁻, junto con la autoprotólisis del agua')+st('Preguntas de comprensión:',['¿Qué errores desde el marco teórico empleado en clase encuentra?','¿Qué puede señalar respecto de la magnitud de las disociaciones sucesivas del anión?','¿Cómo podría explicar el comportamiento ácido-base de esta sal?','¿La autoprotólisis del agua estará siempre presente?']).replace('<ol type="a">','<ol start="8">'),'GUÍA 1 · INTEGRACIÓN TEÓRICA · 8 a 11');
  g.done();

  // ===================== GUÍA N° 3 · monopróticos (Ácido-base I) =====================
  g=guide('acido-base','g3m','Guía 3 · Ácidos y bases monopróticos','<p>Guía N° 3: análisis sistemático del equilibrio ácido-base. La prioridad es el <b>análisis cualitativo del sistema</b>; el resultado del cálculo debe ser coherente con el análisis.</p>','GUÍA 3 · MONOPRÓTICOS','g3m');
  const g3m=[
    ['HNO₃ 0,050 M','Calcule las concentraciones de catión hidronio y anión oxhidrilo en una solución de ácido nítrico 0,050 M.'],
    ['HCl 36 % diluido','Calcular el pH de la solución que se obtiene cuando 0,07 mL de solución de ácido clorhídrico 36 % m/m se diluyen a 500 mL a 25 °C. La densidad de la solución concentrada es 1,179 g/mL.'],
    ['Diluir 10 veces',['Calcule la variación de pH que ocurrirá al diluir 10 veces los siguientes sistemas:',['agua pura;','solución 0,025 M de ácido clorhídrico;','solución 0,025 M de hidróxido de sodio.']]],
    ['Electrolitos fuertes: pH y pOH',['Calcule el pH y pOH de las siguientes soluciones de electrolitos fuertes:',['Ácido iodhídrico 0,0356 M','Ácido clorhídrico 0,0725 M','Hidróxido de bario 0,0092 M','Hidróxido de sodio: 13,6 mg se disuelven hasta un volumen final de 350 mL de solución','Ácido bromhídrico: 75 mL de solución 3,5·10⁻⁴ M se diluyen hasta volumen final de 500 mL']]],
    ['Ácido fórmico 0,1 M','Calcular el pH y la concentración de todas las especies en equilibrio de una solución de ácido fórmico de concentración 0,1 M. Ka: 1,78·10⁻⁴.'],
    ['Ácido periódico 2·10⁻⁴ M','Calcular el pH, concentración de todas las especies en equilibrio y grado de disociación de una solución de ácido periódico 2·10⁻⁴ M. Ka: 0,162.'],
    ['Urea 0,0446 M','Calcular el pH, concentración de todas las especies en equilibrio y grado de disociación de una solución de urea 0,0446 M. Kb: 1,20·10⁻¹⁴.'],
    ['Piperidina 0,039 M','Calcular el pH y grado de disociación de una solución 0,039 M de piperidina. Kb: 1,60·10⁻³.'],
    ['Ácido benzoico con α = 2,4 %','El grado de disociación porcentual se calcula como el grado de disociación multiplicado por 100, y se escribe como porcentaje. Una solución de ácido benzoico 0,110 M tiene un grado de disociación de 2,4 %, lo cual significa que hay un 2,4 % disociado. Calcular el pH de la solución y la constante de acidez.'],
    ['Metilamina 35 % diluida','Se tiene una solución acuosa de metilamina (CH₃NH₂) 35 % m/m, con densidad 0,85 g/mL. Un volumen de 50 mL de esta solución se diluye hasta un volumen final de 1 L. Calcular el pH de la solución final y la concentración de todas las especies en equilibrio.'],
    ['Ácido propanoico diluido','El ácido propanoico, CH₃CH₂COOH, tiene una constante de acidez 1,3·10⁻⁵. Una muestra de 50 mL de ácido 0,250 M se diluye a un volumen final de 1 L. Calcular la concentración de todas las especies presentes.'],
    ['Ácido láctico a tres concentraciones',['El ácido láctico es producido por los músculos durante el ejercicio físico. Calcule el pH, pOH y grado de disociación para el anión, de cada una de las siguientes soluciones acuosas de ácido láctico (CH₃CH(OH)COOH). Ka: 8,4·10⁻⁴.',['0,12 M','1,2·10⁻³ M','1,2·10⁻⁵ M']]],
    ['HF 22,6 M diluido',['Se dispone de una solución de ácido fluorhídrico 22,6 M, pKa: 3,17. Se diluyen 5 cm³ hasta 2 dm³ con agua. Calcular:',['pH de la solución final;','concentración de fluoruro en equilibrio en ambas soluciones.']]],
    ['Preparar NH₃ de pH 11','Se requiere preparar 500 mL de solución de amoníaco a pH 11. Sabiendo que la constante de basicidad es 1,8·10⁻⁵, calcular la concentración de la solución y la masa de solución concentrada 50 % m/m que debería utilizarse.'],
    ['HClO 1·10⁻⁶ M','Calcular el pH y el grado de disociación de una solución de ácido hipocloroso de concentración 1·10⁻⁶ M. Ka: 2,95·10⁻⁸.']
  ];
  const put=(g,list)=>list.forEach(([t,s],i)=>g.add(i+1,t,Array.isArray(s)?st(s[0],s[1]):st(s)));
  put(g,g3m);g.done();

  // ===================== GUÍA N° 2 · Estudio cualitativo de la disociación =====================
  g=guide('acido-base-2','g2','Guía 2 · Estudio cualitativo de la disociación','<p>Guía N° 2. Los ítems de soluciones reguladoras (15, 18, 20, 21 y 22) están en la sección <b>Buffer</b>, y los de la plata con cloruro y el cobre con amoníaco (8 y 17), en <b>Complejos</b>.</p>','GUÍA 2','g2');
  g.add(1,'¿Cuál es el ácido más fuerte?',st('Decidir de los siguientes pares, cuál es el ácido o base más fuerte: HF o HIO₃ y HNO₂ o HCN. pKa (HF): 3,45; pKa (HIO₃): 0,77; pKa (HNO₂): 3,37; pKa (HCN): 9,31.'));
  g.add(2,'Ordenar ácidos por acidez',st('Ubique los siguientes ácidos en orden creciente de acidez: ácido nitroso pKa 3,37; ácido cloroso pKa 2,00; ácido fluorhídrico pKa 3,45; ácido fórmico pKa 3,75; ácido cianhídrico pKa 9,31.'));
  g.add(3,'Ordenar bases por fuerza',st('Ubique las siguientes bases en orden de fuerza creciente: ion fluoruro pKa 3,45; amoníaco pKb 4,75; ion acetato pKa 4,75; piridina pKb 8,75; hidracina pKb 5,77; ion hipobromito pKa 8,6.'));
  g.add(4,'pH del agua pura a 50 °C',st('Calcular el pH de agua pura a 50 °C. Kw (50 °C): 5,5·10⁻¹⁴.'));
  g.add(5,'Verdadero o falso',st('Indicar V o F y justificar cualitativamente los siguientes enunciados:',['Una solución 0,1 M de cloruro de amonio (amoníaco electrolito débil, ácido clorhídrico electrolito fuerte) tendrá pH ácido.','Una solución 10⁻⁸ M de ácido clorhídrico tendrá pH básico.','Una solución 0,1 M de acetato de calcio tendrá pH neutro.','Una solución 1 M de arseniato diácido de sodio será básica.']));
  g.add(6,'Comportamiento ácido-base de sales',st('Explicar el comportamiento ácido-base de las siguientes sales. Utilice las tablas para obtener las constantes de equilibrio que precise.',['nitrato de potasio;','nitrato de amonio;','bisulfito de sodio;','iodato de metilamonio.']));
  g.add(7,'HCl diluido y agregado de NaCl',st('Una solución de ácido clorhídrico se prepara diluyendo 2,34 mL de ácido concentrado 36 % m/m, densidad 1,19 g/mL, hasta un volumen final de 250 mL. Si se agregan 10 gramos de cloruro de sodio a la solución, ¿cambia el pH? ¿El pH final será ácido, básico o neutro?'));
  g.add(9,'Describir sistemas',st('Describir el sistema de las siguientes especies, explicando por qué se escribe de esa forma:',['Hidróxido de estroncio','Ácido bromhídrico','Ácido carbónico. Ka₁: 4,7·10⁻⁷; Ka₂: 5,6·10⁻¹¹','Ácido fluorhídrico. Ka: 3,5·10⁻⁴','Piridina. Kb: 1,5·10⁻⁹']));
  g.add(10,'Diagramas de especiación de esas 5 especies',st('Confeccionar el diagrama de especiación de las 5 especies indicadas en el ítem anterior, e indicar el rango de pH en que existe cada especie.'));
  g.add(11,'Por qué esta descripción del NH₄HSO₄ está mal',st('Se realiza la descripción cualitativa de todos los procesos posibles de una solución de sulfato ácido de amonio (ácido sulfúrico: 1.ª disociación fuerte, 2.ª disociación débil; amoníaco: electrolito débil). Explique por qué la siguiente descripción no es correcta, justificando con los conceptos teóricos apropiados:')+'<p class="qacGuideEq">NH₄HSO₄(ac) → NH₄⁺(ac) + HSO₄⁻(ac)<br>HSO₄⁻(ac) → SO₄²⁻(ac) + H₃O⁺(ac)<br>NH₄⁺(ac) → NH₃(ac) + H₃O⁺(ac)</p>');
  g.add(12,'Jugo de limón: especie predominante',st('El jugo de limón debe su carácter ácido fundamentalmente al ácido cítrico. El ácido cítrico es un ácido triprótico, cuyas constantes son las siguientes: pKa₁ = 3,15; pKa₂ = 4,77; pKa₃ = 6,40. Sabiendo que el pH del jugo de limón es 2,3, indique cuál es la especie que predomina en el jugo de limón.'));
  g.add(13,'Sangre a pH 7,4: ¿alguna especie despreciable?',st('El pH de la sangre suele oscilar muy poco alrededor de 7,4. Sabiendo que el equilibrio es fundamentalmente regulado por la presencia de ácido carbónico, justifique si a ese pH existe alguna especie derivada del ácido cuya concentración sea despreciable. pKa₁: 6,36; pKa₂: 10,33.'));
  g.add(14,'Leer Ka desde diagramas de especiación',st('Determinar los valores de Ka e intervalos de pH de predominio de cada especie presente en los siguientes diagramas de especiación:')+`<figure class="kitFigure qiPhoto"><img src="./assets/quimica-cualitativa/guia2-ej14-diagramas.webp" alt="Tres diagramas de especiación de la Guía 2, ejercicio 14" loading="lazy"><figcaption>Diagramas originales de la guía (1, 2 y 3 de arriba hacia abajo).</figcaption></figure>`);
  g.add(16,'Describir sistemas finales',st('Describa el sistema final (en caso de que sean 2 sustancias, considere 1 mol de cada una):',['Nitrato de sodio (ácido nítrico: electrolito fuerte; hidróxido de sodio: electrolito fuerte)','Nitrito de sodio (ácido nitroso: electrolito débil; hidróxido de sodio: electrolito fuerte)','Ácido nítrico y ácido clorhídrico (ambos electrolitos fuertes)','Cloruro de trimetilamonio (ácido clorhídrico: electrolito fuerte; trimetilamina: electrolito débil)','Nitrato de sodio y ácido nítrico (ácido nítrico: electrolito fuerte; hidróxido de sodio: electrolito fuerte)','Nitrito de sodio y ácido nitroso (ácido nitroso: electrolito débil; hidróxido de sodio: electrolito fuerte)','Metilamina (electrolito débil)','Metilamina y ácido clorhídrico (ácido clorhídrico: electrolito fuerte; metilamina: electrolito débil)','Metilamina e hidróxido de calcio (metilamina: electrolito débil; hidróxido de calcio: electrolito fuerte)','Hidróxido de calcio y ácido clorhídrico (ambos electrolitos fuertes)','Hidróxido de calcio y ácido acético (ácido acético: electrolito débil; hidróxido de calcio: electrolito fuerte)']));
  g.add(19,'pH de los sistemas no reguladores del ítem 16',st('Para los sistemas NO reguladores del ítem 16 justifique si el pH del medio será ácido, básico o neutro.'));
  g.done();

  // ===================== GUÍA N° 3 · polipróticos y desafíos (Ácido-base II) =====================
  g=guide('acido-base-2','g3p','Guía 3 · Ácidos y bases polipróticos y problemas desafío','','GUÍA 3 · POLIPRÓTICOS','g3p');
  put(g,[
    ['H₂S saturado 0,1 M','Calcule la concentración de iones hidronio en una solución saturada de ácido sulfhídrico, cuya concentración puede estimarse en 0,1 M. Ka₁: 9,6·10⁻⁸; Ka₂: 1,3·10⁻¹⁴.'],
    ['H₂SO₄ de pH 2,5','Calcule el grado de disociación de todas las especies en equilibrio en una solución de ácido sulfúrico cuyo pH es 2,5. Ka₂: 1,2·10⁻².'],
    ['H₂S con HCl: [H₃O⁺] = 0,3 M','A una solución de ácido sulfhídrico se le agrega ácido clorhídrico tal que la concentración de iones hidronio es 0,3 M. Indique cuáles serán las especies relevantes en el equilibrio.'],
    ['H₃PO₄ 0,2 M','Calcule la concentración de todas las especies en el equilibrio y su grado de disociación para una solución 0,2 M de ácido fosfórico. pKa₁: 2,3; pKa₂: 7,2; pKa₃: 13,0.'],
    ['Ácido ascórbico a pH 3','La vitamina C químicamente es ácido ascórbico, un ácido diprótico, cuyas constantes de disociación son 8,0·10⁻⁵ y 1,6·10⁻¹². Calcule el grado de disociación porcentual de todas las especies presentes en una solución de ácido ascórbico cuyo pH sea 3.'],
    ['Nicotina diluida 1:10','Una solución de nicotina (pKb₁: 4; pKb₂: 10,9) 0,1 M se diluye 1:10. Determinar si en la solución final el pH de la solución será básico. Calcular el pH de la solución final.'],
    ['Ácido arsénico 0,2 M','Calcule la concentración de todas las especies en equilibrio en una solución acuosa de ácido arsénico 0,2 M. Compare los resultados obtenidos con la solución del ej. 4. pKa₁: 2,24; pKa₂: 6,93; pKa₃: 11,50.']
  ]);
  g.add('d1','Desafío 1 · ácido oxálico',st('Una solución se prepara disolviendo 1 g de ácido oxálico dihidratado hasta 2 L de solución. Analizar el sistema y determinar en qué rango se encontrará el pH de la solución preparada. pKa₁: 1,3; pKa₂: 4,3.'),'GUÍA 3 · PROBLEMA DESAFÍO 1');
  g.add('d2','Desafío 2 · ácido L-ascórbico cosmético y ácido nicotínico',
    '<p>Albert Szent-Györgyi nació en Hungría en 1893. En 1930 asumió la jefatura del Instituto de Química Médica de la Facultad de Medicina de la Universidad de Szeged, una de las regiones más prestigiosas de Hungría en la producción del famoso “paprika” húngaro (pimentón). Una noche, su esposa le sirvió pimentón crudo en la cena, que Szent-Györgyi guardó y analizó al día siguiente en su instituto: encontró en él un contenido muy alto del ya famoso ácido hexurónico, permitiendo el aislamiento no de gramos, sino de 3 kg de este compuesto. Esto permitió que se aceleraran sus investigaciones y, con su colaborador americano Svirbely, consiguiera identificar los efectos biológicos de esta molécula. El ácido hexurónico resultó ser la mundialmente buscada vitamina C, también conocida como ácido L-ascórbico, nombre que se debe al efecto de la molécula en prevenir y tratar el escorbuto. Por este descubrimiento, y otros relacionados con el ciclo de Krebs y los ácidos fumáricos, fue galardonado en 1937 con el Premio Nobel de Medicina. Szent-Györgyi opinaba —mucho antes de la época de la globalización e internet— que el cerebro no está para cargarlo con demasiados datos memorísticos, sino para pensar, preguntar en forma adecuada y buscar las respuestas. Por eso, lea detenidamente y piense antes de responder el siguiente examen:</p>'+
    '<p>El ácido L-ascórbico (H₂C₆H₆O₆) es un ácido diprótico de múltiples usos. Sus constantes de disociación son 8,0·10⁻⁵ y 1,6·10⁻¹². Desde hace varios años se utiliza como principio activo cosmético en diferentes productos. Es uno de los pocos compuestos que se ha probado científicamente que su uso sostenido tiene la capacidad de reducir los efectos del envejecimiento, debido a su capacidad de reaccionar con los radicales libres y proteger frente al estrés oxidativo, además de intervenir positivamente en la síntesis de colágeno. Para que el ácido L-ascórbico tenga efectividad cosmética, se requiere que el producto contenga entre un 10 % y 20 % (m/v).</p>'+
    st('<b>1.</b> Considere que en los productos cosméticos el ácido L-ascórbico se encontrará en base acuosa y, por lo tanto, su comportamiento será coincidente con el exhibido en una solución. Bajo esta premisa:',['Describa el sistema que compone el ácido ascórbico en situación de equilibrio. Justifique la descripción detalladamente.','Justifique cuál o cuáles de las especies del ácido ascórbico serán las que tengan acción cuando se coloque el producto en contacto con la piel, sabiendo que el pH de la piel normal varía entre 4,7 y 5,7.','Calcule la concentración de todas las especies en un producto cosmético cuya concentración es 12,5 % m/v de ácido L-ascórbico.'])+
    '<p>Los productos con ácido L-ascórbico no se recomiendan utilizar junto a tratamientos anti-acné, para evitar reacciones de oxidación dérmica. Uno de los tratamientos clásicos dermatológicos para el acné consiste en la aplicación tópica de una solución de ácido nicotínico (C₆H₅NO₂, constante de acidez: 1,4·10⁻⁵) cuyo contenido es: 40 mL de solución contienen 380 mg de ácido nicotínico. En la formulación farmacéutica se incorpora, durante el proceso de producción, ácido clorhídrico hasta llegar a pH 2,5.</p>'+
    st('<b>2.</b> Con los datos anteriores, calcule la cantidad de ácido clorhídrico 36 % m/m (δ = 1,18 g/mL) que debe incorporarse a un lote de producción de 40 litros.'),'GUÍA 3 · PROBLEMA DESAFÍO 2');
  g.done();

  // ===================== GUÍA N° 3 · sales =====================
  g=guide('acido-base-2','g3s','Guía 3 · Sales y desafío del ácido fólico','','GUÍA 3 · SALES','g3s');
  put(g,[
    ['KCN 0,25 M','Calcule el pH de una solución 0,25 M de cianuro de potasio. Ka (HCN) = 7,20·10⁻¹⁰.'],
    ['Sulfocianuro de potasio','Se prepara una solución disolviendo 4,5682 g de sulfocianuro de potasio en 250 mL de agua. Suponiendo que no hay contracción de volumen, calcule el pH de la solución resultante. Ka (HSCN) = 70.'],
    ['Diluir 10 veces acetato de sodio','Calcule el cambio de pH cuando se diluye 10 veces una solución 2·10⁻¹ M de acetato de sodio.'],
    ['KNO₂ 0,2 M','Calcule la concentración de aniones oxhidrilo y el pH que existen en una solución 0,2 M de nitrito de potasio.'],
    ['Porcentaje de hidrólisis de NaCN 0,1 M','Se define como porcentaje de hidrólisis al porcentaje, respecto de la cantidad de sal inicial que se disuelve, que sufre la reacción de hidrólisis. Calcule el porcentaje de hidrólisis de una solución 0,1 M de cianuro de sodio.'],
    ['Acetato de sodio de pH 9,3','Calcule la concentración de una solución de acetato de sodio cuyo pH es 9,3.'],
    ['Ka de HA a partir del pH de KA','Un cierto ácido débil que denominaremos HA forma una sal de potasio que llamaremos KA. Si la solución de KA tiene una molaridad de 0,15 y su pH es 8,5, ¿cuál es la constante de disociación de HA?'],
    ['Kb del amoníaco desde el % de hidrólisis','Una solución de cloruro de amonio 10⁻³ M se encuentra hidrolizada en un 0,074 %. ¿Cuál es la constante de disociación del amoníaco?'],
    ['Cloruro de metilamonio 2,0 M','Calcule el pH de una solución 2,0 M de cloruro de metilamonio. pKb (metilamina) = 3,36.'],
    ['Nitrato de amonio para pH 5,4','Calcule la cantidad en gramos de nitrato de amonio que deben adicionarse a un litro de agua para tener una solución acuosa con un pH de 5,4.'],
    ['Benzoato de amonio 10⁻² M','Calcule el pH de una solución 10⁻² M de benzoato de amonio.'],
    ['Cianuro de amonio 0,3 M','Calcule la concentración de iones oxhidrilo de una solución de cianuro de amonio 0,3 M.']
  ]);
  g.add('f','Desafío · ácido fólico',
    '<p>Lucy Wills fue una hematóloga británica que, a fines de los años 20 y principios de los 30 del siglo XX, condujo una investigación en la India sobre la anemia macrocítica en el embarazo. Una observación clave realizada en 1931 guió la identificación del folato como un nutriente requerido para prevenir la anemia durante el embarazo: Wills demostró que la anemia podía ser revertida con levadura de cerveza. El folato fue identificado como una sustancia contenida en la levadura de cerveza durante 1930.</p>'+
    '<p>El ácido fólico es administrado a mujeres en búsqueda de un embarazo, o cursando el primer trimestre de embarazo, con el objetivo de prevenir deformaciones en la placenta que supondrían el aborto, y defectos en el feto resultantes del mal cierre del tubo neural en el cerebro (anencefalia) y la columna vertebral (espina bífida). El folato es necesario para la producción y mantenimiento de nuevas células, por ser necesario para la replicación del ADN. Esto es especialmente importante durante periodos de división y crecimiento celular rápido, como en la infancia y el embarazo. Por esto, la deficiencia de folato dificulta la síntesis y división celular, afectando principalmente la médula ósea, un sitio de recambio celular rápido.</p>'+
    st('<b>1.</b> Sabiendo que el pH fisiológico en sangre es 7,4 y considerando que el ácido fólico (pKa₁: 2,3; pKa₂: 8,3) se comportará en sangre exactamente igual que en agua:',['Describa el sistema del ácido fólico en equilibrio.','Justifique cuál o cuáles de las especies del ácido fólico serán despreciables a pH fisiológico.','Calcule la concentración de todas las especies a pH fisiológico.'])+
    '<p>En el estómago se encuentran los jugos gástricos, que provienen de secreciones de diferentes órganos del sistema digestivo, los cuales cambian su composición según si el cuerpo humano se encuentra en situación de ayuno (como ocurre al despertar) o realizando la digestión de alimentos. Al ingerir alimentos, el jugo gástrico se modifica hasta obtenerse una solución de ácido clorhídrico de pH 1.</p>'+
    st('<b>2.</b> Considerando que el volumen de jugo gástrico a pH 1 que elabora el estómago diariamente es entre 1,5 y 2 litros y sabiendo que la dosis de ácido fólico es 1 comprimido de 5 mg, justifique si afectará de forma notoria el pH del estómago cuando se ingiere.')+
    '<p>En una empresa farmacéutica evalúan la posibilidad de usar sales sódicas de folato en lugar de ácido fólico.</p>'+
    st('<b>3.</b> Recordando que el ácido fólico es diprótico:',['Discuta el carácter ácido-base de todas las sales de sodio del ácido fólico y explique en cada caso.','Establezca cómo será la magnitud de las disociaciones del folato de sodio a pH fisiológico sanguíneo.','Calcule la concentración de anión folato en el estómago luego de consumir 1 comprimido.']),'GUÍA 3 · SALES · PROBLEMA DESAFÍO');
  g.done();

  // ===================== BUFFER · Guía 2 y Guía 3 =====================
  g=guide('buffer','bg2','Guía 2 · Soluciones reguladoras','','GUÍA 2','b-g2');
  g.add(15,'Funcionamiento de una solución reguladora',st('Explique el funcionamiento de una solución reguladora, empleando como ejemplo el sistema carbonato ácido / carbonato.'));
  g.add(18,'NaOH 0,2 M con ácido acético 0,4 M',st('Se homogenizan 100 mL de solución de hidróxido de sodio 0,2 M (electrolito fuerte) con 100 mL de solución de ácido acético 0,4 M (electrolito débil). Informe si la solución se trata de una solución reguladora, y justifique su dictamen.'));
  g.add(20,'Reguladores del ítem 16 ante ácido o base',st('Para los sistemas reguladores del ítem 16 (Guía 2, en la sección Ácido-base II) explique cómo responderá el sistema en caso del agregado de ácido o base.'));
  g.add(21,'Ca(OH)₂ con ácido cloroacético: ¿pH 8,5?',st('Se mezclan 100 mL de solución de hidróxido de calcio (electrolito fuerte) 0,25 M con 50 mL de solución de ácido cloroacético 0,5 M (electrolito débil). El equipo informa que el pH del sistema es 8,5.',['Justifique si el pH informado puede ser posible para esta solución.','¿Es una solución reguladora? Justifique.']));
  g.add(22,'Verdadero o falso',st('Indique verdadero o falso y justifique:',['Una solución de cloruro de amonio es capaz de regular el pH.','Una solución de amoníaco es ácida porque tiene amonios.','Una solución de ácido sulfhídrico es capaz de regular el pH.']));
  g.done();

  g=guide('buffer','bg3','Guía 3 · Soluciones reguladoras y desafío','','GUÍA 3 · REGULADORAS','b-g3');
  put(g,[
    ['Elegir el ácido para pH 3,1','Utilizando los siguientes ácidos, elija y justifique cuál será el más adecuado para preparar una solución reguladora a pH 3,1: peróxido de hidrógeno (pKa: 11,65), ácido propanoico (pKa: 4,874), ácido cianoacético (pKa: 2,472), ácido 4-aminobencensulfónico (pKa: 3,232).'],
    ['Cloruro de imidazol e imidazol',['Se prepara una solución disolviendo 1,00 g de cloruro de imidazol y 1,00 g de imidazol (pKb: 7,007) en 100 mL de agua. Considerando despreciable la variación de volumen:',['Calcule el pH de la solución inicial. ¿Constituye una solución reguladora?','Calcule el pH de la solución luego de la incorporación de 2,30 mL de ácido perclórico 1,07 M.']]],
    ['HClO₄ para llevar imidazol a pH 6,993','Calcule la cantidad en mL de ácido perclórico 1,07 M que se debe añadir a una solución 1 % m/V de imidazol para dar un pH 6,993.'],
    ['Ácido cloroacético y cloroacetato','Calcule el pH de una solución preparada mezclando 0,08 moles de ácido cloroacético (pKa: 2,865) con 0,04 moles de cloroacetato de sodio en 1,00 L de agua.'],
    ['Na₂CO₃ para NaHCO₃ 5 % a pH 10','Calcule la masa en gramos de carbonato de sodio que debe agregarse a una solución de carbonato ácido de sodio 5 % m/v para obtener una solución reguladora a pH 10.'],
    ['NaOH para ácido salicílico a pH 3,50','Calcule el volumen de hidróxido de sodio 0,202 M que se debe añadir a 25 mL de solución de ácido salicílico (pKa: 2,97) 0,230 M para ajustar el pH a 3,50.'],
    ['Reguladora de pH 5,50 con ácido oxoacético','Indique cómo sería posible preparar una solución reguladora a pH 5,50 partiendo de los siguientes componentes: oxoacetato sódico 0,100 M, ácido oxoacético (pKa: 3,46), solución de ácido clorhídrico 1,0 M y solución de hidróxido de sodio 1,0 M. Nota: no realice cálculos, justifique en forma teórica su elección.'],
    ['Ortofosfato en el plasma a pH 8,5','El equilibrio de aniones del ortofosfato, en concentración 0,01 M, es uno de los principales responsables de regular el pH del plasma sanguíneo a pH 7,4. ¿Será útil este sistema de aniones si el pH del plasma fuera 8,5?'],
    ['¿La solución salina regula?','La solución salina normal es un líquido inyectable que se utiliza ampliamente en caso de internaciones. Se compone de una solución 0,9 % m/V de cloruro de sodio. Sabiendo que el pH aproximado de la sangre es 7,4, justifique si la solución salina se trata de una solución reguladora.'],
    ['Reguladora de pH 2 con Na₂SO₄ y H₂SO₄','Diseñe una solución reguladora a pH 2, a partir de sulfato de sodio y ácido sulfúrico.'],
    ['Ácido carbónico en el plasma','La fracción líquida y acelular de la sangre se denomina plasma. En el plasma se encuentran todos los sistemas reguladores requeridos para mantener el balance del pH fisiológico en torno a 7,4. Uno de los principales sistemas reguladores lo constituyen especies del ácido carbónico. Sabiendo que tenemos 4 litros de sangre, calcule la relación de concentraciones de especies del ácido carbónico para mantener el pH regulado.'],
    ['Grupo 3: reguladora de pH 10 y sulfuros','En el grupo 3 de la marcha analítica de cationes se utiliza una solución reguladora a pH 10. Dicha solución se utiliza para aumentar la concentración de sulfuros en solución. Justifique lo anterior en base a los conceptos teóricos apropiados.'],
    ['Ácido bórico para un baño de pies','Las soluciones de ácido bórico y sus sales sódicas se utilizan como antimicóticos en la prevención del pie de atleta, en solución reguladora a pH 10. Esto se basa en que los hongos requieren para su crecimiento un pH entre 4,5 y 5,5. Justifique cómo estaría compuesta la dosis a utilizar para un baño pédico, considerando que se utilizarían 500 mL de agua para disolver los componentes. Considere que tanto el ácido como sus sales los puede conseguir en estado sólido y al 80 % de pureza.']
  ]);
  g.add('mtx','Desafío · metotrexato inyectable',
    '<p>Las soluciones inyectables suelen ser muy utilizadas cuando se requieren efectos rápidos. Esto es especialmente útil en las salas de emergencia y quirófanos, donde se requiere rapidez y precisión en las dosis inoculadas al paciente. Muchos de los medicamentos a utilizar por vía intravenosa tienen un pH similar al del plasma sanguíneo para evitar efectos indeseados como la ruptura de glóbulos rojos. El metotrexato es un principio activo que se agrupa entre los antagonistas del ácido fólico, para el tratamiento de distintos tipos de cáncer y terapia de mantenimiento en combinación con otros agentes quimioterapéuticos en diferentes tumores sólidos y linfomas no Hodgkin, así como en artritis y psoriasis. Si bien se puede utilizar en comprimidos, en terapias oncológicas se suele utilizar como solución inyectable. En esta presentación tiene un pH de 7,5–9,0. Si bien la molécula de metotrexato no tiene incidencia en el pH de la solución, su uso por vía parenteral obliga a la regulación del pH.</p>'+
    '<p>Se está diseñando un ensayo de laboratorio para definir las concentraciones de los excipientes, o sea, de los componentes que acompañan al metotrexato en la formulación farmacéutica. En el laboratorio se dispone de los siguientes compuestos: ácido fosfórico solución 85 % m/m (densidad: 1,685 g/mL; pKa₁: 2,148; pKa₂: 7,199; pKa₃: 12,15), hidróxido de sodio 98 % pureza, hidróxido de calcio 85 % pureza, ácido nítrico 63 % m/m (densidad: 1,63 g/mL), amoníaco 28 % m/v (pKa = 9,26), fosfato de sodio 99 % pureza, nitrato de amonio 92,5 % pureza, ácido bórico 99 % pureza (pKa₁ = 9,14; pKa₂ = 12,7; pKa₃ = 13,8).</p>'+
    '<ol><li>Indique y justifique cuál o cuáles serán los componentes ideales para preparar la solución reguladora en la formulación farmacéutica. Considere que se requiere la mayor capacidad reguladora posible.</li><li>Describa el sistema regulador y calcule la relación de concentraciones entre el par ácido / base conjugado de la solución reguladora.</li><li>Calcule la cantidad de los compuestos elegidos en el ítem 1 para la elaboración de 100 litros de formulación farmacéutica.</li><li>Justifique cualitativamente:'+ol(['¿Podría haber utilizado otro par de compuestos para regular el pH de la formulación farmacéutica?','¿Podría utilizar acetato de amonio para regular este pH?'])+'</li><li>Responda brevemente y justifique:'+ol(['¿Cómo será la expresión de balance de carga y masa de acetato de amonio? ¿El pH de esta solución será dependiente del pH?','¿Por qué una solución a pH = 2,0 de ácido clorhídrico y ácido acético puede resolverse despreciando el aporte de acidez del ácido acético?'])+'</li></ol>','GUÍA 3 · REGULADORAS · PROBLEMA DESAFÍO');
  g.done();

  // ===================== GUÍA N° 4 · precipitación =====================
  const g4intro='<p>Guía N° 4: análisis sistemático del equilibrio de sistemas combinados. La prioridad es el <b>análisis cualitativo del sistema</b>; el resultado del cálculo debe ser coherente con el análisis. Se pueden emplear las tablas de constantes (machete lateral).</p>';
  g=guide('precipitacion','pg4','Guía 4 · Precipitación (ejercicios 1 a 10 y 17)',g4intro,'GUÍA 4','p-g4');
  g.add(1,'Kps a partir de la solubilidad',st('Calcule la constante de producto de solubilidad de:',['Ioduro de plata, sabiendo que exactamente 2,9·10⁻⁶ g de sal son solubles en 1 litro de agua. Suponga que la densidad de la solución es 1.','Fluoruro de estroncio, sabiendo que se determinó por espectrometría que la concentración de estroncio en una solución saturada de fluoruro de estroncio es 1,11·10⁻¹ g/L.','Cromato de plata, sabiendo que la cantidad máxima de cromato de plata que puede disolverse en 100 mL de agua es 4,35 mg a 25 °C.']));
  g.add(2,'Solubilidad del iodato cúprico y temperatura',st('Sabiendo que la constante de producto de solubilidad a cierta temperatura del iodato cúprico es 1,4·10⁻⁷, calcule la solubilidad a esa temperatura. Sabiendo que la disolución de esta sal es exotérmica, ¿cómo varía su solubilidad con la variación de temperatura?'));
  g.add(3,'Catión que permanece disuelto',st('Calcule la concentración de catión que permanece disuelto en las siguientes situaciones:',['Hidróxido férrico en una solución 0,3 M de hidróxido de sodio. ¿Cómo y por qué podría disolver este hidróxido modificando el pH de la solución?','Ioduro de plomo, en % m/v, en una solución 0,2 M de ioduro de calcio. ¿Cómo y por qué podría modificar la solubilidad del precipitado por modificación del pH de la solución?']));
  g.add(4,'Sulfato de bario que queda en solución',st('Calcule la masa en gramos de sulfato de bario que permanecerá en solución cuando a 250 mL de solución 0,1 M de nitrato de bario se adicionan 600 mL de solución 1 M de sulfato de potasio. ¿Cuál será la masa de sal que quedará insoluble?'));
  g.add(5,'Fluoruro mínimo para precipitar CaF₂',st('Una solución es 0,02 M con respecto a los iones calcio. ¿Cuál será la concentración de iones fluoruro mínima, expresada en molaridad, que debe adicionarse para que comience la precipitación de fluoruro de calcio?'));
  g.add(6,'Mg²⁺ máximo en buffer amoniacal',st('Calcule la máxima concentración de iones magnesio, en molaridad, que pueden existir en una solución reguladora conformada por 0,4 M de cloruro de amonio y 0,1 M de amoníaco.'));
  g.add(7,'¿Precipita el hidróxido férrico?',st('Prediga si precipitará hidróxido férrico si a 100 mL de solución que contiene 10 mg de iones férricos se incorpora 1 mL de solución 1 M de amoníaco.'));
  g.add(8,'¿Qué precipita primero?',st('Prediga qué precipita primero en las siguientes situaciones:',['A una solución que contiene 0,01 M de iones cloruro y 0,001 M de iones bromuro se le incorpora, gota a gota, una solución 0,01 M de nitrato de plata.','Se incorpora gota a gota una solución diluida de cromato de potasio a otra que contiene 10 g de iones plata y 10 g de iones plomo en 1 litro de solución.']));
  g.add(9,'Sulfuro de cobalto en H₂S saturado a pH 3',st('Se considera que una solución saturada de sulfuro de hidrógeno tiene una concentración total de 0,1 M del ácido. A esta solución saturada se le incorpora un ácido fuerte hasta pH 3, y cationes cobalto (II) hasta 0,01 M. ¿Precipitará el sulfuro de cobalto? ¿Cómo y por qué podría modificar el sistema para favorecer la precipitación total de los cationes? ¿Y para favorecer la disolución del precipitado?'));
  g.add(10,'Plomo y manganeso con sulfuro',st('En una solución que contiene iones plomo e iones manganeso con concentraciones iguales a 0,1 M, se hace burbujear sulfuro de hidrógeno hasta que se observa que ya no se forma más precipitado. ¿Cuál será la concentración de cada ion que todavía permanece en solución? Considere que la concentración molar de sulfuros en solución es 1,2·10⁻¹⁵ M. ¿Cómo podría hacer para garantizar la precipitación total de ambas sales de sulfuros?'));
  g.add(17,'Kps del fosfato ácido de calcio a pH 7,5',st('Se sabe que a pH = 7,5 se pueden disolver como máximo 10 mg de fosfato ácido de calcio por cada 100 mL de agua. Calcular el Kps de la sal en esas condiciones. Ka (H₃PO₄): Ka₁ 7,11·10⁻³; Ka₂ 6,34·10⁻⁸; Ka₃ 4,22·10⁻¹³.'));
  g.done();

  // ===================== GUÍA N° 4 · redox =====================
  g=guide('redox','rg4','Guía 4 · Redox (ejercicios 20 a 26)',g4intro,'GUÍA 4','r-g4');
  g.add(20,'K entre estaño metálico y dicromato',st('Calcule la constante de equilibrio para la reacción entre el estaño metálico y el anión dicromato, en medio ácido. E° Cr₂O₇²⁻|Cr³⁺ = 1,33 V; E° Sn⁴⁺|Sn(s) = −0,009 V.'));
  g.add(21,'Hierro y estaño: variación de potencial',st('Calcular la variación de potencial que ocurre cuando se reduce hierro metálico con estaño en solución acuosa, sabiendo que la concentración de hierro como ion será 0,300 M, y la de estaño como ion será 0,500 M. E° Fe²⁺|Fe(s) = −0,440 V; E° Sn²⁺|Sn(s) = −0,136 V.'));
  g.add(22,'Pila de plomo y dicromato',st('Una forma de representar procesos redox es expresándolos como una pila como la siguiente:')+'<p class="qacGuideEq">Pb(s) | PbSO₄(s) | Na₂SO₄ (0,300 M) ‖ Cr₂O₇²⁻ (0,160 M), Cr³⁺ (0,270 M), H₃O⁺ (0,400 M) | Pt</p>'+st('Lo anterior puede leerse como: en el ánodo el plomo sólido se oxida a sulfato plumboso en medio de sulfato de sodio, y la concentración de esta última sal es 0,300 M; en el cátodo el anión dicromato se reduce a catión cromo 3+ en medio ácido empleando un electrodo de platino. Las concentraciones de cada ion están entre paréntesis. Sabiendo que E° Pb²⁺|Pb(s) = −0,126 V y E° Cr₂O₇²⁻|Cr³⁺ = 1,33 V, responda:',['¿Funcionaría esta pila en medio básico?','¿Cuál es el potencial final medido en la pila?']));
  g.add(23,'Pila de dicromato y permanganato',st('Calcular el potencial de esta pila:')+'<p class="qacGuideEq">Pt | Cr³⁺ (0,125 M), Cr₂O₇²⁻ (0,200 M), H₃O⁺ (0,600 M) ‖ MnO₄⁻ (0,150 M), Mn²⁺ (0,400 M), H₃O⁺ (0,250 M) | Pt</p><p>E° Cr₂O₇²⁻|Cr³⁺ = 1,33 V; E° MnO₄⁻|Mn²⁺ = 1,51 V.</p>');
  g.add(24,'Kps del AgCl a partir de potenciales',st('Exprese el Kps del cloruro de plata en función de los potenciales normales de electrodo de AgCl|Ag(s) y Ag⁺|Ag(s). Calcule el valor numérico. E° AgCl|Ag(s) = 0,22 V; E° Ag⁺|Ag(s) = 0,80 V.'));
  g.add(25,'Kf del complejo a partir de una pila',st('Un sistema compuesto por dos recipientes se conecta de forma tal de armar una pila. Al colocar el puente salino (recuerde lo que sabe de teoría de pilas), se mide con voltímetro una diferencia de potencial de 0,099 V. Calcular la constante de formación del complejo.')+'<p class="qacGuideEq">Zn(s) | Zn(CN)₄²⁻ (0,450 M), CN⁻ (2,65·10⁻¹ M) ‖ Zn²⁺ (3,84·10⁻⁴ M) | Zn(s)</p>');
  g.add(26,'Pila Ce⁴⁺/Ce³⁺ frente a plata con cloruro',st('Se mezclan 100 mL de solución 2,5·10⁻² M de Ce⁴⁺ con 100 mL de una solución 2,5·10⁻³ M de Ce³⁺, y se llevan a 250 mL en un medio regulado a pH = 2. El sistema resultante se conecta a través de un puente salino y un electrodo de platino con otro sistema compuesto por: 100 mL de nitrato de plata 10⁻³ M, 100 mL de solución de ácido clorhídrico 0,1 M y un electrodo de plata (s).',['Describa la pila resultante, y el sentido de circulación de la corriente al cerrarse el circuito.','La masa de nitrato de mercurio que hay que agregar a la hemicelda de Ag⁺|Ag(s) para lograr que la corriente que circula sea despreciable.']));
  g.done();

  // ===================== COMPLEJOS · Guía 2 (8 y 17) y Guía 4 (11–16, 18, 19) =====================
  g=guide('complejos','cg','Guía 2 y Guía 4 · Complejos y equilibrios combinados',g4intro,'GUÍA 4','c-g4');
  g.add('g2-8','Plata con HCl: ¿se puede usar NaCl?',st('Se tiene una solución de nitrato de plata 0,1 M. Se le agrega gota a gota solución de ácido clorhídrico concentrado (electrolito fuerte). Aparece un precipitado color blanco, y luego se disuelve en solución acuosa. Justifique empleando argumentos teóricos si puede reemplazar el ácido clorhídrico con cloruro de sodio.'),'GUÍA 2 · EJ. 8');
  g.add('g2-17','Cobre con amoníaco / cloruro de amonio y luego HNO₃',st('Se prepara una solución de sulfato cúprico (color azul). Se incorpora solución equimolar de amoníaco (electrolito débil) y cloruro de amonio hasta aparición de un precipitado. Luego, se continúa agregando la misma solución hasta disolución total del precipitado. La disolución final es de un color azul intenso. Por último, se agregan 5 gotas de ácido nítrico 0,1 M. No se observan cambios.',['Esquematice la sucesión de eventos ocurridos en la situación experimental presentada, justificando si el sistema se encuentra en equilibrio o fuera de él.','Justifique empleando los argumentos teóricos apropiados por qué ocurren los cambios identificados en a.','Explicar por qué no se produjeron cambios al incorporar el ácido nítrico.']),'GUÍA 2 · EJ. 17');
  g.add(11,'AgCl en amoníaco 0,1 M',st('El cloruro de plata tiene una solubilidad en medio acuoso de 1,26·10⁻⁵ M. Indicar cualitativamente cómo se modifica la cantidad de sal disuelta en una solución de amoníaco 0,1 M en comparación con la cantidad disuelta en agua pura. Justificar.'));
  g.add(12,'Zinc y cianuro',st('Se sabe que el catión zinc, en presencia de cianuro, puede formar un complejo muy estable tetracoordinado. Sabiendo que la constante de formación global del complejo es 1·10¹⁸ a temperatura ambiente, calcular la concentración de todas las especies presentes en el equilibrio cuando a 250 mL de una solución de catión metálico 1,5·10⁻³ M se le agregan 500 mL de una solución de ligando 1 M. Considerar despreciables los procesos de hidrólisis.'));
  g.add(13,'[Co(en)₃]³⁺',st('El cobalto (III), en presencia de etilendiamina (en), forma el complejo [Co(en)₃]³⁺, cuya Kf vale 4,9·10⁴⁸ a temperatura ambiente. Si una solución que contiene 2·10⁻³ M de dicho complejo se formó partiendo de una dada concentración de Co³⁺ y de etilendiamina 1 M, calcular la concentración del catión metálico en el equilibrio.'));
  g.add(14,'Ag₂S con cianuro',st('Calcular la concentración mínima de cianuro total necesaria para disolver 0,1 moles por litro de sulfuro de plata. ¿Es posible realizar este proceso en el laboratorio?'));
  g.add(15,'PbSO₄ con bromuro',st('Se tienen 10⁻³ moles de PbSO₄(s) en contacto con 150 mL de sobrenadante. Calcular la concentración mínima de Br⁻ libre que tiene que existir en el equilibrio para disolver todo el PbSO₄. Considerar despreciable la hidrólisis del ion sulfato.'));
  g.add(16,'AgX con tiosulfato',st('A partir de 4·10⁻⁴ moles de AgX precipitado se quieren preparar 100 mL de una solución de compuesto de coordinación. Determinar el mínimo volumen de tiosulfato de sodio 0,1 M que será necesario agregar para disolver dicho precipitado y obtener la solución. pKps AgX = 12,1.'));
  g.add(18,'NaCl máximo con plata amoniacal',st('Se tienen 50,0 mL de una solución 0,01 M en nitrato de plata sobre la que se agregan 50,0 mL de amoníaco 1,00 M. ¿Cuál es la máxima cantidad de NaCl sólido (en gramos) que podrá disolverse sin que aparezca precipitado? Puede suponer que el amoníaco no hidroliza en estas condiciones, que los volúmenes son aditivos y que el agregado de sólido no modifica el volumen.'));
  g.add(19,'Sulfocianuro mínimo para ver 1 ppm de Fe³⁺',st('El color provocado por el complejo Fe(SCN)²⁺ lo puede apreciar cualquier persona que no tenga un defecto visual como daltonismo, a partir de concentración 6,4·10⁻⁶ M. Calcule cuál es la concentración mínima de sulfocianuro de potasio que se requiere para determinar 1 ppm de catión férrico en muestras de aguas naturales. Kf (Fe(SCN)²⁺) = 1,4·10².'));
  g.done();

  // ===================== GUÍA N° 4 · ejercicios de integración =====================
  g=guide('complejos','g4int','Guía 4 · Ejercicios de integración','<p>Los dos ejercicios de integración de la Guía N° 4, completos: combinan ácido-base, soluciones reguladoras, precipitación, complejos y redox.</p>','GUÍA 4','g4-int');
  g.add(1,'Integración 1 · marcha analítica de cationes',
    '<p>La Química Analítica es la ciencia que estudia el conjunto de principios, leyes y técnicas cuya finalidad es la determinación de la composición química de una muestra natural o artificial. La Química Analítica Cualitativa y Cuantitativa tiene por objeto el reconocimiento o identificación de los elementos o de los grupos químicos presentes en una muestra. El Análisis Químico es el conjunto de técnicas operatorias puestas al servicio de la Química Analítica. (Fuente: Guía TP Q. A. Cualitativa. Prof. C. Casali)</p>'+
    '<p>Se entiende por <b>marcha analítica</b> un conjunto de reglas prácticas que, fundándose en el conocimiento de las propiedades de los iones, de las leyes por las que se rigen las reacciones y de las circunstancias en que éstas se verifican, tiene por objeto separar de manera sistemática los diversos iones contenidos en un problema para proceder a su definitivo reconocimiento. (Fuente: Química Analítica Cualitativa. Burriel, Lucena, Arribas, Hernández)</p>'+
    '<ol>'+
    '<li>La identificación de catión plata en el primer grupo se realiza empleando 2 reacciones: una con ioduro de potasio y otra con ácido nítrico, ambas partiendo del compuesto de coordinación de plata con amoníaco.'+ol(['Justifique cualitativamente la reacción de identificación de plata con ácido nítrico con las herramientas teóricas que considere necesarias.','Justifique cuantitativamente la reacción de identificación de plata con ioduro de potasio, sabiendo que la concentración de plata total es 10⁻³ M, la concentración de amoníaco total es 10⁻¹ M y que se incorpora reactivo hasta una concentración total de 10⁻² M. Kf (Ag(NH₃)₂⁺): 1,6·10⁷; Kps (AgI): 8,52·10⁻¹⁷; Kb (NH₃): 1,8·10⁻⁵. Emplee el esquema de la marcha analítica para responder.'])+'</li>'+
    '<li>Para separar cobre y cadmio de bismuto y plomo, en el segundo grupo de cationes, se utiliza amoníaco concentrado. Justifique si precipita el hidróxido de cobre (II) sabiendo que la concentración de cobre total es 10⁻⁴ M y la concentración de amoníaco total es 5·10⁻³ M. Para realizar estos cálculos, suponga que no hay cadmio en el tubo de ensayos. Kps (Cu(OH)₂): 4,8·10⁻¹⁶; Kf (Cu(NH₃)₄²⁺): 1,1·10¹³; Kb (NH₃): 1,8·10⁻⁵.</li>'+
    '<li>El cuarto grupo de cationes comienza así: a la solución con Ca²⁺, Sr²⁺, Ba²⁺, Mg²⁺, K⁺, Na⁺ y NH₄⁺ se agrega (NH₄)₂CO₃ en medio NH₃ / NH₄Cl; precipitan CaCO₃, SrCO₃ y BaCO₃ (blancos) y quedan en solución Mg²⁺, K⁺, Na⁺ y NH₄⁺. Justifique si al comenzar se están utilizando soluciones reguladoras. En caso afirmativo, describa y analice el sistema regulador considerando máxima capacidad de regulación.</li>'+
    '<li>La reacción de identificación de manganeso es una reacción redox donde, por reacción con bismutato de sodio en medio ácido, se obtiene una coloración violeta intensa.'+ol(['Se mide la variación de potencial y la lectura del voltímetro indica 0,23 V. Justifique si el sistema está en equilibrio.','Calcule la constante de equilibrio de la reacción.'])+'</li></ol>','GUÍA 4 · INTEGRACIÓN 1');
  g.add(2,'Integración 2 · los pigmentos de Sorolla',
    '<p>Joaquín Sorolla y Bastida fue un pintor español impresionista. Si bien nació cuando el movimiento de Francia estaba ya en pleno apogeo, reúne todas las características que conocemos bien de esta corriente artística: gusto por el aire libre, búsqueda de lo momentáneo y fugaz, captación de los efectos de la luz, ausencia del negro y de los contornos, pinceladas pequeñas, sueltas e independientes. La temática de Sorolla es variada, pero dos temas son muy reiterativos: las playas y las costumbres y trajes populares.</p>'+
    '<p>Numerosos historiadores han estudiado la paleta de colores del artista y se determinó que Sorolla utilizó una paleta de colores altamente tóxica. El resultado de las obras estudiadas del pintor arroja que utilizaba pigmentos mezclados con metales, práctica hoy en día prohibida. Entre los pigmentos empleados estaban el blanco de plomo (carbonato plumboso), el rojo de mercurio (sulfuro mercúrico) y el verde de París (arseniato cúprico). De esta forma, los cuadros son tan bellos como tóxicos.</p>'+
    '<ol><li>Se analiza una fracción de color verde de un cuadro y se encuentra blanco de plomo y verde de París siguiendo el siguiente procedimiento: se disuelve empleando ácido nítrico y se analiza por absorción atómica, encontrando una concentración total de plomo de 4·10⁻⁴ M y de cobre 2·10⁻² M.'+ol(['Justifique cualitativamente el procedimiento empleado al disolver la muestra.','¿Podría reemplazar ácido nítrico por ácido clorhídrico?'])+
    '<p>Para separar los metales de los pigmentos se agrega amoníaco hasta concentración 0,1 M y cloruro de amonio hasta concentración 0,75 M.</p>'+
    '<ol type="a" start="3"><li>Al agregar estos 2 reactivos, ¿qué ocurre? ¿Qué tipo de sistema se establece en la solución? Analice cualitativamente su disociación.</li><li>Despreciando la formación del precipitado, calcule la cantidad de amoníaco libre en el sistema.</li><li>¿Es correcto despreciar la formación del precipitado? Responda cualitativamente.</li></ol></li>'+
    '<li>Se analiza una fracción color rojo del mismo cuadro, disolviendo con agua regia. Se obtiene en solución el ion tetracloromercuriato (II). Se hierve la solución para eliminar completamente los nitratos.'+ol(['Justifique si habrá reacción por agregado de una sal de ioduro de potasio.'])+
    '<p>Se trata la solución para obtener el catión mercúrico sin complejar. A esta solución se le agrega solución de cloruro estañoso hasta que la diferencia de potencial medida es 0,23 V. Se observa la aparición de un precipitado negro.</p>'+
    '<ol type="a" start="2"><li>Justifique si el sistema está en equilibrio.</li><li>Calcule la constante de equilibrio de la reacción ocurrida.</li></ol></li></ol>','GUÍA 4 · INTEGRACIÓN 2');
  g.done();

  // ---------------------------------------------------------------------
  // 3) Orden de los bloques de ejercicios: guías primero (en su orden), después el resto
  // ---------------------------------------------------------------------
  data.units.forEach(u=>{
    const th=u.sections.filter(s=>!s.exercises),ex=u.sections.filter(s=>s.exercises);
    const rank=s=>{const i=GUIDES.indexOf(s.key.replace('qac-ej-',''));return i<0?100:i};
    ex.sort((a,b)=>rank(a)-rank(b));
    u.sections=[...th,...ex];
  });
})();
